ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ2 ヒアリング"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "2-1:お客様から頂いた意見を活かして、提案資料を作成した。")),
                NOT(INCLUDES(CompletionBasis__c, "2-2: お客様に提案を実施し、仮説課題に対して意見交換ができた。")),
                NOT(INCLUDES(CompletionBasis__c, "2-3: より具体的案提案をするため、次回のアポイントが取れた。"))
            )
        )
    )
)
